/// <reference lib="webworker" />

import { generateDeterministicWorld } from './DeterministicWorldGenerator';
import type { GeneratedWorldConfig } from './GeneratedWorldTypes';

declare const self: DedicatedWorkerGlobalScope;

self.onmessage = (event: MessageEvent<GeneratedWorldConfig>) => {
  const data = generateDeterministicWorld(event.data);
  self.postMessage(data, [
    data.elevation.buffer,
    data.waterSurface.buffer,
    data.flowAccumulation.buffer,
    data.flowDirectionX.buffer,
    data.flowDirectionZ.buffer,
    data.river.buffer,
    data.lake.buffer,
    data.moisture.buffer,
    data.forest.buffer,
    data.rockiness.buffer,
    data.fuel.buffer,
  ]);
};

export {};
